UPDATE companies SET description='Ocotillo Solar Electric was founded in 2016 in Albuquerque, New Mexico, by Dominic Westeen. The company began as a locally owned and operated residential solar installer with a focus on bringing high-quality, low-cost solar installations and exemplary customer service to homeowners in the Albuquerque metro area and surrounding communities.

The firm specializes in residential solar photovoltaic design, installation, and maintenance, along with off-grid and battery backup system design and installation. It also provides service and repair work for existing PV systems, roof replacement removal and re-installation of solar arrays, third-party design consultation, and EV charger installation. Since 2016 the team has completed hundreds of home installations across New Mexico, and its collective experience exceeds 1,000 systems.

Ocotillo serves residential homeowners in Albuquerque, Rio Rancho, Corrales, Bernalillo, Placitas, Los Lunas, Belen, Tijeras, Cedar Crest, Sandia Park, and the East Mountains. Customers typically seek grid-tied solar arrays, battery storage for backup power, or EV charging infrastructure, and the company manages permitting, utility interconnection, and incentive paperwork on their behalf.

The company emphasizes its local presence, NABCEP-certified leadership, and a community giving program that has donated over $15,000 to nonprofits since 2017. It partners with distributors to supply modules, inverters, batteries, and EV chargers with warranties, aiming to match quality with low-cost installation.', certifications=ARRAY['NABCEP Certified PV Installation Professional','New Mexico Electrical Contractor License #387291','REC Certified Solar Professional','REIA Board Member']::text[], profile='{"capabilities": ["Residential Solar PV Design", "Solar PV Installation", "Solar PV Maintenance", "Off-Grid System Design and Installation", "Battery Backup Design and Installation", "PV System Service and Repair", "Roof Replacement Removal and Re-Installation of PV Systems", "Third-Party Design Consultation and Review", "EV Charger Installation"], "industries": ["Residential solar installation", "Renewable energy", "Electrical contracting"], "materials": ["Solar PV modules", "Inverters", "Battery storage systems", "EV charging equipment"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Locally owned and operated in Albuquerque, NM", "Led by NABCEP-certified PV Installation Professionals", "Low-cost installation paired with top-tier product warranties", "Community giving program: donation per system sold since 2017", "Hundreds of residential installations completed since 2016"], "facts_used": ["Founded 2016 -> db, /, /about", "Headquarters Albuquerque, New Mexico -> db, /, /about", "Owner Dominic Westeen -> /, /about", "Locally owned and operated -> /, /about", "NABCEP-certified installers lead staff -> /, /about, /services", "Hundreds of NM homes installed since 2016 -> /, /about", "Team collective experience over 1,000 installations -> /about", "Services: residential PV design/install/maintenance, off-grid, battery backup, service/repair, roof R&R, consulting, EV charger -> /services", "Service area: Albuquerque and surrounding towns -> /, /about, /services", "Community giving program since 2017, over $15,000 donated -> /about", "Certifications: NABCEP PV Installation Professional (Dominic Westeen #091308-37), NM Electrical Contractor #387291, REC Certified Solar Professional, REIA Board Member -> /about", "Products used: modules, inverters, EV chargers, batteries -> /services"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "Ocotillo Solar Electric is a full-service residential solar company specializing in the installation and design of solar pv systems.", "founded_year": "2016", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='ocotillo-solar-electric' AND approved AND profile IS NULL;
UPDATE companies SET description='Olympia Sheet Metal, Inc. was founded in April 1990 in Tumwater, Washington, by Hans Rebitzer, a 25-year veteran of the sheet metal trade. The company began as a five-person shop and grew to a 30-person operation within four years. It remains family-owned and is led by Helga Rebitzer as president.

The firm operates as a full-service sheet metal contractor and HVAC contractor. Its fabrication shop produces custom architectural sheet metal — including roof flashings, kitchen hoods, wall panels, and custom ductwork — in stainless steel, brass, bronze, aluminum, and steel. It also designs, installs, and services commercial and industrial HVAC systems, offering preventive maintenance, retro‑commissioning, boiler and chiller service, and 24/7 emergency repair. The workforce consists of union craftsmen from Sheet Metal Workers Local 66, many with ten to twenty years of tenure.

Customers span healthcare (hospitals, laboratories), commercial real estate (office buildings, banks, restaurants, hotels, shopping centers), industrial manufacturing, government agencies, municipalities, schools, universities, and religious institutions across Pierce, Thurston, Lewis, and Mason counties. Projects range from simple repairs to multi‑million‑dollar fast‑track installations.

The company emphasizes craftsmanship, safety, and duct‑cleanliness standards for healthcare and food‑service environments. Its differentiators include a family‑owned culture, union‑trained staff, OSHA 30/10 safety programs, and quality‑control procedures that prevent mold and airborne contaminants in ductwork.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom sheet metal fabrication", "Architectural sheet metal fabrication", "HVAC duct fabrication and installation", "Commercial HVAC installation, repair, and maintenance", "Industrial HVAC and sheet metal services", "Preventive maintenance programs", "24/7 emergency HVAC service", "Refrigeration service", "Process ventilation design and installation", "Fume exhaust systems", "Laboratory equipment service", "Kitchen equipment service", "Pollution and dust control systems", "Energy efficiency testing", "Thermal imaging", "Custom stainless steel fabrication", "Custom brass fabrication", "Custom bronze fabrication", "Custom aluminum fabrication", "Custom steel fabrication", "Kitchen hood fabrication", "Roof flashing fabrication", "Retro\u2011commissioning services", "Boiler and chiller service"], "industries": ["Healthcare", "Commercial real estate", "Industrial manufacturing", "Government", "Education", "Hospitality", "Food service", "Retail", "Religious institutions"], "materials": ["Stainless steel", "Brass", "Bronze", "Aluminum", "Steel"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Family-owned and operated since 1990", "Union craftsmen (Sheet Metal Workers Local 66)", "24/7 emergency HVAC service", "Custom architectural fabrication in stainless steel, brass, bronze, aluminum, and steel", "OSHA 30/10 safety training and duct\u2011cleanliness quality controls"], "facts_used": ["Founded April 1990 as 5-person shop -> /about", "Founder Hans Rebitzer, 25-year industry veteran -> /about", "Grew to 30-person operation within four years -> /about", "Family-owned, operated by Rebitzer family with Helga Rebitzer as president -> /about", "Union tradesmen from Sheet Metal Workers Local 66 -> /about", "Services: commercial HVAC, industrial HVAC, architectural sheet metal -> /services", "Industries served: hospitals, office buildings, government agencies, municipalities, manufacturing, healthcare facilities, restaurants, hotels, universities, schools, factories, supermarkets, churches, warehouses -> /about", "Safety training: OSHA 30-hour for foremen/techs, OSHA 10-hour for other tradesmen -> /about", "Quality control procedures for duct cleanliness in healthcare and food industries -> /about", "Materials: custom stainless steel, brass, bronze, aluminum, steel -> /services", "24/7 emergency HVAC service -> /services", "Preventive maintenance programs (semi-annual/quarterly) -> /services", "Location: Lacey, WA serving Pierce, Thurston, Lewis, Mason counties -> /", "Headquarters: Tumwater, Washington -> db", "Founded year 1990 -> db"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Olympia Sheet Metal, Inc. is a leading, family owned HVAC contractor delivering heating and air conditioning solutions, and architectural metal services to commercial and industrial clients throughout the South Sound.", "founded_year": "1990", "employee_count": "30 (1994)", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='olympia-sheet-metal-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Omega Circuits & Engineering was founded in 1980 in New Brunswick, New Jersey, as a privately owned manufacturer of high‑technology printed circuit boards. The company grew from modest beginnings to its current 18,000‑square‑foot custom industrial space on two acres, serving a customer base of more than 200 companies that includes military outfits and leaders in electronics and communications.

The shop fabricates rigid PCBs ranging from standard single‑ and double‑sided boards to complex multilayers up to 18 layers, HDI with blind and buried vias, aluminum‑based boards for thermal management, and heavy‑copper designs up to 9 oz. It also provides turnkey assembly — surface‑mount, through‑hole, wire‑harness, box‑build and functional testing — with prototype runs completed in as little as 48 hours. In‑house capabilities extend to copper chem‑mill services, aluminum milling and anodizing, and micro‑section analysis to IPC or military standards.

Omega’s customers operate in high‑frequency/RF microwave, defense, communications and medical industries. The company emphasizes working side‑by‑side with engineers to make designs manufacturable and cost‑competitive, often taking on jobs that other facilities decline.

Differentiators cited by the company include free micro‑section verification on heavy‑copper jobs up to 6 oz, free inventory warehousing for production orders, just‑in‑time consignment programs, and a quality system built on UL approval, ISO 9002 registration and adherence to IPC Class III and MIL‑55110 specifications.', certifications=ARRAY['UL approved','ISO 9002','RoHS']::text[], profile='{"capabilities": ["Single\u2011 and double\u2011sided PCB fabrication", "Multilayer PCB fabrication up to 18 layers", "HDI with blind and buried vias", "Aluminum\u2011based PCB fabrication", "Heavy copper PCB fabrication up to 9 oz", "Micro\u2011section analysis (IPC / military)", "Surface\u2011mount technology (SMT) assembly", "Through\u2011hole (PTH) assembly", "Wire\u2011harness assembly", "Box\u2011build and functional testing", "Turnkey (consigned or turnkey) assembly", "Artwork layout from schematic or sample", "Copper chem\u2011mill service", "Aluminum milling and anodizing", "LPI solder mask (multiple colors)", "Legend printing (multiple colors)", "Surface finishes: HAL, immersion tin, immersion nickel, immersion silver, immersion gold, hard gold, wire\u2011bondable gold, ENIG, anodizing", "Electrical test: flying probe, hi\u2011pot, universal grid (bed\u2011of\u2011nails)", "Micro\u2011section evaluation with solder float", "IPC\u2011TM\u2011650 and IPC\u2011A\u2011600H test procedures", "Just\u2011in\u2011time inventory programs", "Prototype and small\u2011volume production", "Design\u2011for\u2011manufacturability review"], "industries": ["High Frequency / RF Microwave", "Defense", "Communications", "Medical"], "materials": ["FR4 (all Tg)", "Aluminum", "Polyimide", "PTFE (Teflon)", "Rogers laminates", "Arlon laminates", "Taconic laminates", "Isola laminates", "Bergquist thermal materials", "Nelco laminates"], "equipment": ["Digital microscopes (calibrated annually)", "Flying probe tester", "Universal grid test (bed\u2011of\u2011nails)", "Hi\u2011pot tester"], "volume": "Prototype to mass production", "lead_time": "48 hours for prototypes", "tolerances": "", "built_on": ["Prototypes fabricated in 48 hours", "Free micro\u2011section on heavy\u2011copper jobs up to 6 oz", "Free inventory warehousing for production orders", "Turnkey assembly with consigned\u2011material programs", "In\u2011house aluminum milling, anodizing and copper chem\u2011mill"], "facts_used": ["Founded 1980 -> /about", "Headquarters New Brunswick, NJ -> /about", "Privately owned -> /about", "18,000 sq ft facility -> /about", "200+ customers -> /about", "Prototypes in 48 hours -> /about, /services", "Capabilities: up to 18 layers, HDI, aluminum PCBs, heavy copper up to 9 oz -> /services", "Turnkey assembly: SMT, PTH, wire harness -> /services", "Materials: FR4, Aluminum, Polyimide, Teflon, Rogers, Arlon, Taconic, Isola, Bergquist, Nelco -> /services", "Certifications: UL approved, ISO 9002, RoHS -> /quality", "Industries: High Frequency/RF Microwave, Defense, Communications, Medical -> /, /about", "Differentiators: free micro-section on heavy copper, free inventory warehousing -> /services", "Equipment: digital microscopes, flying probe, universal grid test, hi-pot test -> /services"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Omega Circuits & Engineering Corp. is a privately owned manufacturer of high-technology printed circuit boards founded 1980.", "founded_year": "1980", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='omega-circuits-engineering' AND approved AND profile IS NULL;
